import (
	"fmt"
	"strconv"
)

func parse(text string) (int, error) {
	result := 0
	var err error

	if text != "" {
		result, err = strconv.Atoi(text) // updates the outer names
	}

	return result, err
}

func main() {
	value, err := parse("42")
	fmt.Println(value, err) // 42 <nil>
}
