package main

import "fmt"

func choose(enabled bool) (int, error) {
	count := 0
	if !enabled {
		return count, nil
	}

	loaded, err := loadCount()
	if err != nil {
		return 0, err
	}
	return loaded, nil // ownership is explicit; no shadowed update
}

func loadCount() (int, error) { return 12, nil }

func main() {
	for _, enabled := range []bool{false, true} {
		value, err := choose(enabled)
		fmt.Println(enabled, value, err)
	}
}
